SELECT DISTINCT T.* FROM(
SELECT * FROM ( select MATCH_SEQNO, concat_ws('', 'GROUP_ID',GROUP_ID) GROUP_ID, REMARK, TRU_SEQ_NO, TRU_ACCOUNT, TRU_PS, CASE TRU_PS WHEN '${CD_FLOW_01}' THEN '${T01}' ELSE '${T02}' END ps, TRU_PRINAMT, TRU_SELLER, TRU_SELLERNAME, TRU_USAGE, SYS_TRADE_ID, SYS_IS_TOTAL_TRADE, SYS_CDATE, SYS_BUSS_TYPE, SYS_PORTFOLIO_ID, SYS_PORTFOLIO_NAME, SYS_FINPROD_ID, SYS_FINPROD_NAME, SYS_PRINAMT, SYS_CCY, NULL profitType, null finprodId FROM LQD_PIPELINE_MATCH where group_id in ( SELECT GROUP_ID from LQD_PIPELINE_MATCH left join PTL_CAPACCT_INFO on LQD_PIPELINE_MATCH.SYS_PORTFOLIO_ID = PTL_CAPACCT_INFO.PORTFOLIO_ID
null) OR SYS_PORTFOLIO_ID in (
#{item} )
AND TRU_PS = #{cdFlowFlag}
AND TRU_SELLER = #{counterAcctNo}
AND PTL_CAPACCT_INFO.ACCT_NO = #{tgAcctNo}
AND SYS_CDATE >= STR_TO_DATE(#{cashDateStart},'%Y-%m-%d')
AND SYS_CDATE <= STR_TO_DATE(#{cashDateEnd},'%Y-%m-%d')
AND SYS_BUSS_TYPE = #{bizType}
AND (instr(REMARK, #{remark}) > 0)
) ORDER BY GROUP_ID )
UNION ALL
SELECT NULL MATCH_SEQNO, T4.TOTLE_TRADE_ID GROUP_ID, NULL REMARK, NULL TRU_SEQ_NO, NULL TRU_ACCOUNT, NULL TRU_PS, NULL PS, NULL TRU_PRINAMT, NULL TRU_SELLER, NULL TRU_SELLERNAME, NULL TRU_USAGE, IFNULL(T4.P_TOTLE_TRADE_ID, T4.TOTLE_TRADE_ID) SYS_TRADE_ID, '${YES}' SYS_IS_TOTAL_TRADE, t4.SETTLE_DATE SYS_CDATE, t5.PA_BUSS_TYPE SYS_BUSS_TYPE, t4.PORTFOLIO_ID SYS_PORTFOLIO_ID, t7.PORTFOLIO_NAME SYS_PORTFOLIO_NAME, case when t6.FINPROD_MARKET_ID is not null then t6.FINPROD_MARKET_ID else finRateInfo.BENCHMARK_ID end SYS_FINPROD_ID, case when t6.FINPROD_MARKET_ID is not null then IFNULL(t6.FINPROD_ABBR, t6.FINPROD_NAME) else OPT_TARGET_INFO.TARGET_NAME end SYS_FINPROD_NAME, PAY_ORDERS.SETTLE_AMT SYS_PRINAMT, t4.CCY SYS_CCY, t6.PROFIT_TYPE, T6.FINPROD_ID finprodId FROM TRD_FIN_PRODUCT_DEAL_TOTAL T4 LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T5 ON T4.TOTLE_TRADE_ID = T5.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT_ADD FPA ON T4.CHL_ID = FPA.FINPROD_ID LEFT JOIN FIN_PRODUCT T6 ON T4.FINPROD_ID = T6.FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT_ADD.FINPROD_ID = T6.FINPROD_ID LEFT JOIN PTL_PORTFOLIO T7 ON T4.PORTFOLIO_ID = T7.PORTFOLIO_ID LEFT JOIN (SELECT * FROM STL_PAY_ORDERS T5 WHERE T5.ORDER_ID = (SELECT MAX(T52.ORDER_ID) FROM STL_PAY_ORDERS T52 WHERE T5.TRADE_ID = T52.TRADE_ID)) PAY_ORDERS ON T4.TOTLE_TRADE_ID = PAY_ORDERS.TRADE_ID LEFT JOIN MST_COUNTER_PARTY T8 ON T4.COUNTER_ID = T8.COUNTER_ID LEFT JOIN LQD_PIPELINE_MATCH T9 ON T4.TOTLE_TRADE_ID = T9.SYS_TRADE_ID LEFT JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = T4.FINPROD_ID LEFT JOIN PTL_CAPACCT_INFO PTL ON PTL.PORTFOLIO_ID=T7.PORTFOLIO_ID AND PTL.ACCT_NO = PAY_ORDERS.MY_ACCT_NO left join FIN_RATE_INFO finRateInfo on finRateInfo.FINPROD_ID = T4.FINPROD_ID LEFT JOIN OPT_TARGET_INFO ON finRateInfo.BENCHMARK_ID = OPT_TARGET_INFO.TARGET_ID WHERE ( (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE01}, #{PA_BUSINESS_TYPE02}, #{PA_BUSINESS_TYPE04},#{PA_BUSINESS_TYPE138}, #{PA_BUSINESS_TYPE44}, #{PA_BUSINESS_TYPE45}, #{PA_BUSINESS_TYPE46}, #{PA_BUSINESS_TYPE47}, #{PA_BUSINESS_TYPE48}, #{PA_BUSINESS_TYPE49}, #{PA_BUSINESS_TYPE50}, #{PA_BUSINESS_TYPE38}, #{PA_BUSINESS_TYPE39}, #{PA_BUSINESS_TYPE40}, #{PA_BUSINESS_TYPE41}) AND (FPA.FINPROD_ID IS NULL OR FPA.PAY_TYPE = '01')) OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE77}) AND FPA.PAY_TYPE = '01' AND T4.TRADE_MARKET IN (#{TP01})) OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE51}) AND FPA.PAY_TYPE = '01' AND T4.TRADE_MARKET IN (#{TP01}, #{TP03}, #{TP04}) AND fpt.TYPE_6 = 'H01') OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE35}, #{PA_BUSINESS_TYPE36}, #{PA_BUSINESS_TYPE37}) AND (FPA.FINPROD_ID IS NULL OR FPA.PAY_TYPE = '01') AND T4.TRADE_MARKET IN (#{TP01}))
OR (T5.PA_BUSS_TYPE IN ( #{PA_BUSINESS_TYPE37}) AND FPA.PAY_TYPE = '01' AND T4.TRADE_MARKET IN (#{TP03}, #{TP04}))
OR (T4.TG_BUSI_TYPE IN(#{PA_BUSINESS_TYPE145}, #{PA_BUSINESS_TYPE146}) AND T4.FPRICE_AMT > 0) OR (T4.TG_BUSI_TYPE IN(#{PA_BUSINESS_TYPE147},#{PA_BUSINESS_TYPE148}, #{PA_BUSINESS_TYPE149})) ) AND T4.TRADE_STATUS = #{TRADE_STATUS_01} AND (T4.IS_CANCEL IS NULL OR T4.IS_CANCEL = #{NO}) AND NOT EXISTS (SELECT 1 FROM LQD_PIPELINE_MATCH LPM where T4.TOTLE_TRADE_ID = LPM.SYS_TRADE_ID)
AND PTL.ACCT_NO = #{tgAcctNo}
AND T4.TOTLE_TRADE_ID is null
UNION ALL
SELECT NULL MATCH_SEQNO, T3.ORDER_ID GROUP_ID, NULL REMARK, NULL TRU_SEQ_NO, NULL TRU_ACCOUNT, NULL TRU_PS, T3.PS, NULL TRU_PRINAMT, NULL TRU_SELLER, NULL TRU_SELLERNAME, NULL TRU_USAGE, T3.ORDER_ID SYS_TRADE_ID, '${NO}' SYS_IS_TOTAL_TRADE, T3.SETTLE_DATE SYS_CDATE, '${PA_BUSINESS_TYPE81}' SYS_BUSS_TYPE, T3.PORTFOLIO_ID SYS_PORTFOLIO_ID, t7.PORTFOLIO_NAME SYS_PORTFOLIO_NAME, NULL SYS_FINPROD_ID, NULL SYS_FINPROD_NAME, T3.SETTLE_AMT SYS_PRINAMT, T3.CCY SYS_CCY, NULL PROFIT_TYPE, NULL finprodId FROM STL_DVP_ORDERS T3 LEFT JOIN PTL_PORTFOLIO T7 ON T3.PORTFOLIO_ID = T7.PORTFOLIO_ID LEFT JOIN LQD_PIPELINE_MATCH T9 ON T3.ORDER_ID = T9.SYS_TRADE_ID LEFT JOIN FIN_PRODUCT ON T3.PORTFOLIO_ID = FIN_PRODUCT.FINPROD_MARKET_ID LEFT JOIN FIN_PRODUCT_ADD ON T3.PORTFOLIO_ID = FIN_PRODUCT_ADD.PORTFOLIO_ID LEFT JOIN PTL_CAPACCT_INFO PTL ON PTL.PORTFOLIO_ID=T7.PORTFOLIO_ID AND PTL.ACCT_TYPE = #{A01} WHERE T3.PS = #{PS01} and t3.order_status='01' AND NOT EXISTS (SELECT 1 FROM LQD_PIPELINE_MATCH LPM where T3.ORDER_ID = LPM.SYS_TRADE_ID)
AND PTL.ACCT_NO = #{tgAcctNo}
#{item}
AND FIN_PRODUCT_ADD.PROD_MANAGER IN
#{item}
AND (T3.COUNTER_ACCT_NO IS NULL OR T3.MY_ACCT_NO != T3.COUNTER_ACCT_NO)
AND (T3.SETTLE_DATE is null or T3.SETTLE_DATE >= STR_TO_DATE(#{cashDateStart},'%Y-%m-%d'))
AND (T3.SETTLE_DATE is null or T3.SETTLE_DATE <= STR_TO_DATE(#{cashDateEnd},'%Y-%m-%d'))
AND T3.ORDER_ID is null
UNION ALL SELECT NULL MATCH_SEQNO, T3.TRADE_ID GROUP_ID, NULL REMARK, NULL TRU_SEQ_NO, NULL TRU_ACCOUNT, NULL TRU_PS, t3.PS, NULL TRU_PRINAMT, NULL TRU_SELLER, NULL TRU_SELLERNAME, NULL TRU_USAGE, CASE WHEN T5.PA_BUSS_TYPE IN ('${PA_BUSINESS_TYPE80}','${PA_BUSINESS_TYPE56}', '${PA_BUSINESS_TYPE54}', '${PA_BUSINESS_TYPE58}') THEN T3.TOTLE_TRADE_ID when T5.PA_BUSS_TYPE IN ('${PA_BUSINESS_TYPE65}', '${PA_BUSINESS_TYPE64}', '${PA_BUSINESS_TYPE87}') THEN PAY_ORDERS.ORDER_ID ELSE T3.TRADE_ID END SYS_TRADE_ID, '${NO}' SYS_IS_TOTAL_TRADE, PAY_ORDERS.SETTLE_DATE SYS_CDATE, t5.PA_BUSS_TYPE SYS_BUSS_TYPE, t4.PORTFOLIO_ID SYS_PORTFOLIO_ID, t7.PORTFOLIO_NAME SYS_PORTFOLIO_NAME, t6.FINPROD_MARKET_ID SYS_FINPROD_ID, IFNULL(t6.FINPROD_ABBR, t6.FINPROD_NAME) SYS_FINPROD_NAME, PAY_ORDERS.SETTLE_AMT SYS_PRINAMT, t3.CCY SYS_CCY, t6.PROFIT_TYPE, T6.FINPROD_ID finprodId FROM TRD_PRODUCT_DEAL T3 LEFT JOIN TRD_PRODUCT_DEAL_ADD T4 ON T3.TRADE_ID = T4.TRADE_ID LEFT JOIN PA_TRD_PRODUCT_DEAL T5 ON T4.TRADE_ID = T5.TRADE_ID LEFT JOIN FIN_PRODUCT T6 ON T3.FINPROD_ID = T6.FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD ON T3.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD FPA ON T3.CHL_ID = FPA.FINPROD_ID LEFT JOIN PTL_PORTFOLIO T7 ON T4.PORTFOLIO_ID = T7.PORTFOLIO_ID LEFT JOIN (SELECT * FROM STL_PAY_ORDERS T5 WHERE T5.ORDER_ID = (SELECT MAX(T52.ORDER_ID) FROM STL_PAY_ORDERS T52 WHERE T5.TRADE_ID = T52.TRADE_ID)) PAY_ORDERS ON T3.TRADE_ID = PAY_ORDERS.TRADE_ID LEFT JOIN MST_COUNTER_PARTY T8 ON T3.COUNTER_ID = T8.COUNTER_ID LEFT JOIN LQD_PIPELINE_MATCH T9 ON T3.TRADE_ID = T9.SYS_TRADE_ID LEFT JOIN STL_SEC_ACCT_INFO SSAI ON SSAI.SEC_ACCT_ID = T3.SEC_MANAGE_ACCT_ID AND SSAI.TRD_ACCT_CCY = T3.CCY LEFT JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = T3.TRADE_ID LEFT JOIN PTL_CAPACCT_INFO PTL ON PTL.PORTFOLIO_ID=T7.PORTFOLIO_ID AND PTL.ACCT_NO = PAY_ORDERS.MY_ACCT_NO WHERE ((T5.PA_BUSS_TYPE IN ( #{PA_BUSINESS_TYPE58}, #{PA_BUSINESS_TYPE54}, #{PA_BUSINESS_TYPE56}, #{PA_BUSINESS_TYPE80}, #{PA_BUSINESS_TYPE66}, #{PA_BUSINESS_TYPE67}, #{PA_BUSINESS_TYPE73}, #{PA_BUSINESS_TYPE68}, #{PA_BUSINESS_TYPE61}, #{PA_BUSINESS_TYPE62}, #{PA_BUSINESS_TYPE64}, #{PA_BUSINESS_TYPE87}) and (FPA.PAY_TYPE = '01' or FPA.FINPROD_ID IS NULL)) OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE14}, #{PA_BUSINESS_TYPE34}, #{PA_BUSINESS_TYPE13}, #{PA_BUSINESS_TYPE18}, #{PA_BUSINESS_TYPE15}) AND FPA.PAY_TYPE IS NULL)
OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE10}) AND FPA.PAY_TYPE = '01' AND T3.TRADE_MARKET IN (#{TP01},#{TP03}, #{TP04})) OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE74}) AND FPA.PAY_TYPE = '01' AND T3.TRADE_MARKET IN (#{TP01})) OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE11}) AND T3.PS = #{T39} AND T3.TRADE_MARKET IN (#{TP01}) AND FPA.PAY_TYPE IS NULL)
OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE11}) AND FPA.PAY_TYPE = '01' AND T3.TRADE_MARKET IN (#{TP01})) OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE20}) AND FPA.PAY_TYPE = '01' AND fpt.TYPE_6 = 'H01' AND T3.TRADE_MARKET IN (#{TP01},#{TP03}, #{TP04})) ) AND T3.TRADE_STATUS = #{TRADE_STATUS_01} AND (T3.IS_CANCEL IS NULL OR T3.IS_CANCEL = #{NO}) AND NOT EXISTS (SELECT 1 FROM LQD_PIPELINE_MATCH LPM where T3.TRADE_ID = LPM.SYS_TRADE_ID)
AND PTL.ACCT_NO = #{tgAcctNo}
AND T3.TRADE_ID is null
UNION ALL
SELECT DISTINCT NULL MATCH_SEQNO, T1.SEQNO GROUP_ID, T1.REMARK REMARK, T1.SEQNO TRU_SEQ_NO, T1.ACCOUNT TRU_ACCOUNT, T1.PS TRU_PS, CASE T1.PS WHEN '${CD_FLOW_01}' THEN '${T01}' ELSE '${T02}' END ps, T1.PRINAMT TRU_PRINAMT, T1.SELLER TRU_SELLER, T1.SELLERNAME TRU_SELLERNAME, T1."USAGE" TRU_USAGE, NULL SYS_TRADE_ID, NULL SYS_IS_TOTAL_TRADE, NULL SYS_CDATE, NULL SYS_BUSS_TYPE, NULL SYS_PORTFOLIO_ID, NULL SYS_PORTFOLIO_NAME, NULL SYS_FINPROD_ID, NULL SYS_FINPROD_NAME, NULL SYS_PRINAMT, NULL SYS_CCY, NULL PROFIT_TYPE, NULL finprodId FROM inf_tru_cashflow_daily T1 LEFT JOIN LQD_PIPELINE_MATCH T9 ON T1.SEQNO = T9.TRU_SEQ_NO LEFT JOIN STL_CAPACCT_INFO SCI ON SCI.BUSI_ACCT_NO = T1.ACCOUNT AND T1.CCY = SCI.CCY LEFT JOIN PTL_CAPACCT_INFO PCI ON SCI.ACCT_NO = PCI.ACCT_NO AND SCI.CCY = PCI.CCY AND PCI.ACCT_TYPE = #{A01}
T1.SELLER NOT IN ( SELECT t2.ACCT_NO FROM STL_SEC_ACCT_INFO T3 INNER JOIN STL_CAPACCT_INFO T2 ON T3.TRD_ACCT_ID = T2.ACCT_NO )
AND PCI.ACCT_NO = #{tgAcctNo}
null) OR PCI.PORTFOLIO_ID in (
#{item}
AND T1.PS = #{cdFlowFlag}
AND NOT EXISTS (SELECT 1 FROM LQD_PIPELINE_MATCH LPM where T1.SEQNO = LPM.TRU_SEQ_NO)
AND instr(T1.SELLER, #{counterAcctNo}) > 0
AND T1.CDATE >= STR_TO_DATE(#{cashDateStart},'%Y-%m-%d')
AND T1.CDATE <= STR_TO_DATE(#{cashDateEnd},'%Y-%m-%d')
AND (instr(t1.REMARK, #{remark}) > 0)
)T ORDER BY t.GROUP_ID, T.SYS_CDATE

